INSERT INTO portal_profile_history(id, slug, before_data, after_data, reason, admin_hash) VALUES('october-specs-2026-10-29-gyutan-shio', 'gyutan-shio', '{"slug":"gyutan-shio","displayName":"牛坦しお","description":"初配信2026.10/17 20:00\n\n旅する牛のお姉さん、牛坦しおです。\n\nまだ見ぬ景色を探して、\nふらり、ふわりと旅をしています。\n\n歌ったり、囁いたり、\nあなたの眠れない夜にそっと寄り添ったり。\nいつかどこかで、「しおに会えてよかった」\nそう思ってもらえるような時間を届けたいな🍃\n\n🎧 ASMR🎤 歌ってみた💭 雑談・旅のおはなし\n━━━━━━━━━\n📅 10月17日⏰ 20:00〜\n\nここから、しおの旅がはじまります。\n\n出会えることも、一緒に過ごせる時間も、\nきっとひとつひとつが宝物。\n\n🐄 目標はチャンネル登録者1万人。\n\nまだ何もない小さな旅のはじまりを、\nあなたと一緒に見つけていけたら嬉しいです。\n\n🔗 LINK\n\nHP：［https://lit.link/Gyutan_Sio］\n\n༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ \n【お願い】\n配信やコメント欄では、他の配信者様・活動者様のお名前を出す行為はお控えください。\nまた、他枠で私の名前を出す行為もご遠慮いただけますと幸いです。\n全ての活動物をAI生成ツールへ学習させること禁止しております。\n\nみんなが安心して楽しめる、ゆるっと心地いい空間づくりに\nご協力よろしくお願いいたします🐮🤍\n\n■ 切り抜きルール\n・歌枠「以外」の配信は、切り抜き大歓迎です。【 #牛坦半分こ 】シェアしてくださいね。\n\n■ リスナー様へ\n・みんなで穏やかに、ほっと安心できる時間を過ごしましょう。　　\n\n༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶ ༶\n【Please Read】\n\nTo keep this space comfy and welcoming for everyone, please follow these guidelines.\n\n🐮 Please refrain from mentioning other streamers or creators’ names during my streams or in the comments.\n🐮 Please also avoid mentioning my name in other creators’ streams or communities.\n","avatarUrl":"https://yt3.googleusercontent.com/xFh75gGr0Lka9a1qBNw77iuCR2zcsa5IHf3XIbWw2AeBauYAcn3FWUUsX_Xxf1nQqQ5goeqMJg=s900-c-k-c0x00ffffff-no-rj","agency":"","platform":"YOUTUBE","channelUrl":"https://www.youtube.com/@GyuSio_ch","countryCode":"","languages":[],"tags":[],"xUrl":"","dateState":"FIXED","debutDate":"2026-10-17","debutTime":"20:00","timezone":"Asia/Seoul","startAtUtc":"2026-10-17T11:00:00.000Z","targetMonth":"2026-10","ownerVerified":false,"source":"EXISTING"}', '{"slug":"gyutan-shio","displayName":"牛坦しお","description":"初配信2026.10/17 20:00\n\n旅する牛のお姉さん、牛坦しおです。\n\nまだ見ぬ景色を探して、\nふらり、ふわりと旅をしています。\n\n歌ったり、囁いたり、\nあなたの眠れない夜にそっと寄り添ったり。\nいつかどこかで、「しおに会えてよかった」\nそう思ってもらえるような時間を届けたいな🍃\n\n🎧 ASMR🎤 歌ってみた💭 雑談・旅のおはなし\n━━━━━━━━━\n📅 10月17